/* @lc app=leetcode id=2217 lang=kotlin */ class Solution { fun kthPalindrome(queries: IntArray, intLength: Int): LongArray = ((intLength + 1) / 2).let { h -> Math.pow(10.0, (h - 1).toDouble()).toLong().let { st -> queries.map { q -> (st + q - 1).let { c -> if (c >= st * 10) -1L else c.toString().let { t -> (t + t.dropLast(intLength % 2).reversed()).toLong() } } }.toLongArray() } } }